# Adaptive Bash frontend. Generated by `adaptive init bash`.
#
# Bash has no inline ghost text, so Adaptive powers Tab itself: every TAB
# press queries the engine for what is valid at this position and readline
# inserts or lists the answers. Commands that ship their own completion
# functions keep them untouched -- this registers only the fallback handler
# (`complete -D`) and the first-word predictor (`complete -E`); when the
# engine has nothing, the handler returns 124 so native default completion
# (filenames) takes over unchanged.
#
# The usage profile bootstraps from your history file
# (`adaptive history import ~/.bash_history`) and grows through explicit
# accept feedback reported here; live line recording remains a Zsh-frontend
# feature because Bash offers no reliable preexec hook without third-party
# frameworks.
#
# Requires bash >= 4.0 for `mapfile`; older versions simply stay unregistered.

_adaptive_frontend_available() {
  (( BASH_VERSINFO[0] >= 4 )) || return 1
  command -v adaptive >/dev/null 2>&1
}

# Runs the query protocol for the current readline state and prints the
# sanitized tab-separated stream (header line, then candidate rows).
_adaptive_query() {
  local prefix="${COMP_LINE:0:COMP_POINT}"
  # The protocol counts characters; COMP_POINT counts bytes.
  adaptive query --list --format zsh \
    --buffer "$COMP_LINE" --cursor "${#prefix}" \
    --cwd "$PWD" 2>/dev/null
}

_adaptive_complete() {
  local reply line context value header_seen=0
  # Explicitly initialized: under `set -u`, some bashes treat declared-but-
  # never-assigned arrays as unbound.
  local -a fields=() matches=()
  local -A seen=()
  reply=$(_adaptive_query) || return 124
  [[ -n "$reply" ]] || return 124

  while IFS= read -r line; do
    mapfile -td $'\t' fields <<<"$line"
    if (( ! header_seen )); then
      # Header: request-id, prefix length, candidate count, context key.
      context="${fields[3]:-}"
      context="${context%%$'\n'*}"
      header_seen=1
      continue
    fi
    value="${fields[0]:-}"
    value="${value%%$'\n'*}"
    # Whole-line chain predictions do not fit readline's word-replacement
    # model; everything else is inserted verbatim.
    [[ -n "$value" && "$value" != *" "* && -z "${seen[$value]:-}" ]] || continue
    seen[$value]=1
    matches+=("$value")
  done <<<"$reply"

  if (( ${#matches[@]} == 0 )); then
    return 124
  fi
  # A lone answer is what readline will insert right now; report it so the
  # engine learns the acceptance at this exact position (echoed context key).
  if (( ${#matches[@]} == 1 )) && [[ -n "$context" ]]; then
    (adaptive history feedback accept --context "$context" \
      --value "${matches[0]}" >/dev/null 2>&1) &
    disown
  fi
  COMPREPLY=("${matches[@]}")
  return 0
}

if _adaptive_frontend_available; then
  complete -D -F _adaptive_complete -o filenames
  complete -E -F _adaptive_complete -o filenames
fi
